// Seeds popular Minecraft mods into Supabase pgvector database
// for efficient vector semantic search (match_mods) on mod descriptions.
//
//
// Script Generated by Google AntiGravity, with tweaks, comments and checks by Justin C
// (I wrote this comment!)

import { generateEmbedding } from '../lib/huggingface.js';
import { supabase } from '../lib/supabase.js';
import { searchModrinthMods } from './modrinth.js';
import { searchCurseforgeMods } from './curseforge.js';


/**
* Background seeder that populates Supabase's `mod_embeddings` table with
* popular Minecraft mods across different gameplay categories.
* This ensures vector semantic search (match_mods) has a rich database to query immediately.
* @returns {Promise<void>} - A promise that resolves when the seeding is complete.
 */
export async function seedPopularModEmbeddings(): Promise<void> {
  if (!supabase) {
    return;
  }

  try {
    const { count, error } = await supabase
      .from('mod_embeddings')
      .select('*', { count: 'exact', head: true });

    // if there is an error accessing supabase, return early with a warning message.
    if (error) {
      console.warn('⚠️ [Mod Seeder] Unable to check mod_embeddings count:', error.message);
      return;
    }

    // If we already have at least 100 mods indexed, skip heavy initial seeding
    if (typeof count === 'number' && count >= 100) {
      console.log(`📦 [Mod Seeder] mod_embeddings table already has ${count} mods indexed.`);
      return;
    }

    console.log('🌱 [Mod Seeder] Seeding popular mods into Supabase pgvector database...');

    // Fetch popular mods across core categories
    const categoriesToSeed = [
      '', // top overall
      'technology',
      'magic',
      'adventure',
      'optimization',
      'worldgen',
      'storage',
      'food',
      'decoration',
      'utility',
    ];

    // Fetch mods from each category and add them to a map to avoid duplicates
    const allModsMap = new Map<string, any>();


    for (const category of categoriesToSeed) {
      try {
        // Search modrinth for mods in the current category, sorted by downloads, limiting to 12 mods.
        const mods = await searchModrinthMods({
          query: '',
          categories: category ? [category] : undefined,
          index: 'downloads',
          limit: 12,
        });

        for (const m of mods) {
          // Check if the mod is already in the map to avoid duplicates. If not, add it.
          if (!allModsMap.has(m.externalModId)) {
            allModsMap.set(m.externalModId, m);
          }
        }

        // Then search curseforge for mods in the current category, sorted by downloads, limiting to 12 mods.
        const curseforgeMods = await searchCurseforgeMods({
          query: '',
          categories: category ? [category] : undefined,
          index: 6, // 6 = Sort by Downloads
          limit: 12,
        });

        for (const m of curseforgeMods) {
          // Check if the mod is already in the map to avoid duplicates. If not, add it.
          if (!allModsMap.has(m.externalModId)) {
            allModsMap.set(m.externalModId, m);
          }
        }

      } catch {
        // Continue with other categories if one fails
      }

    }

    const candidateMods = Array.from(allModsMap.values());
    console.log(`🌱 [Mod Seeder] Found ${candidateMods.length} unique popular mods to index.`);

    let indexedCount = 0;
    const batchSize = 8;

    // This next function will handle the batch insertion into the database.
    for (let i = 0; i < candidateMods.length; i += batchSize) {
      const batch = candidateMods.slice(i, i + batchSize);
      const rows = [];

      for (const mod of batch) {
        try {
          const textToEmbed = `${mod.name}: ${mod.summary || ''}`;
          const embedding = await generateEmbedding(textToEmbed);

          if (embedding) {
            rows.push({
              source: mod.source,
              external_mod_id: mod.externalModId,
              title: mod.name,
              summary: mod.summary || mod.name,
              categories: mod.categories || [],
              loaders: mod.loaders || [],
              game_versions: mod.gameVersions || [],
              icon_url: mod.iconUrl || null,
              embedding,
            });
          }
        } catch (err) {
          console.warn(`[Mod Seeder] Failed to embed ${mod.name}:`, err);
        }
      }

      // If there are rows to insert, perform the upsert operation.
      if (rows.length > 0) {
        const { error: upsertErr } = await supabase
          .from('mod_embeddings')
          .upsert(rows, { onConflict: 'source,external_mod_id' });

        // Increment the count of indexed mods if the upsert was successful.
        if (!upsertErr) {
          indexedCount += rows.length;
        } else {
          // If there was an error, log it and don't increment the count.
          console.warn('[Mod Seeder] Batch upsert error:', upsertErr.message);
        }
      }
    }

    console.log(`✅ [Mod Seeder] Successfully indexed ${indexedCount} mods with pgvector embeddings!`);
  } catch (error) {
    console.error('❌ [Mod Seeder] Unexpected error during seeding:', error);
  }
}
